<?php $haySaldo=false;foreach($detalles as $d){if((float)$d['saldo_pendiente']>0){$haySaldo=true;break;}} ?>
<div class="mb-6 flex items-end justify-between"><div><p class="text-sm font-medium text-emerald-600">Pagos al personal</p><h1 class="text-2xl font-bold"><?= htmlspecialchars($periodo['nombre']) ?></h1><p class="text-sm text-slate-500">Estado: <?= htmlspecialchars($periodo['estado']) ?> · pagos totales o parciales.</p></div><a href="index.php?url=planilla_revision&id=<?= $periodo['id_periodo_pago'] ?>" class="rounded-xl border bg-white px-4 py-2 text-sm font-semibold">Volver al detalle</a></div>
<?php if($haySaldo): ?><section class="mb-5 rounded-2xl border border-emerald-200 bg-emerald-50 p-5"><h2 class="font-semibold">Registrar pago</h2><form method="post" action="index.php?url=planilla_pago_registrar" data-confirmar-accion="planilla-pago-registrar" class="mt-4 grid gap-3 sm:grid-cols-2"><?= campoCsrf() ?><input type="hidden" name="id_periodo_pago" value="<?= $periodo['id_periodo_pago'] ?>"><label class="form-label sm:col-span-2">Trabajador<select required name="id_planilla_detalle" class="form-input"><option value="">Seleccione</option><?php foreach($detalles as $d):if((float)$d['saldo_pendiente']<=0)continue;?><option value="<?= $d['id_planilla_detalle'] ?>"><?= htmlspecialchars($d['trabajador'].' · Saldo S/ '.number_format($d['saldo_pendiente'],2)) ?></option><?php endforeach;?></select></label><label class="form-label">Importe<input required min="0.01" step="0.01" type="number" name="importe" class="form-input"></label><label class="form-label">Medio<select name="medio_pago" class="form-input"><option value="TRANSFERENCIA">Transferencia</option><option value="DEPOSITO">Depósito</option><option value="EFECTIVO">Efectivo</option><option value="OTRO">Otro</option></select></label><label class="form-label">Referencia<input name="referencia" maxlength="120" class="form-input"></label><label class="form-label">Observación<input name="observacion" maxlength="250" class="form-input"></label><button class="rounded-xl bg-emerald-600 py-2.5 text-sm font-semibold text-white sm:col-span-2">Registrar pago</button></form></section><?php else: ?><div class="mb-5 rounded-2xl border border-emerald-200 bg-emerald-50 p-4 text-sm font-semibold text-emerald-800">Todos los trabajadores de este período están pagados.</div><?php endif; ?>
<section class="mb-5 overflow-hidden rounded-2xl border bg-white"><div class="border-b p-4"><h2 class="font-semibold">Saldos por trabajador</h2></div><div class="overflow-x-auto"><table data-datatable data-page-options="5,10,25,50" class="min-w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500"><tr><th class="p-4">Trabajador</th><th class="p-4">Neto</th><th class="p-4">Pagado</th><th class="p-4">Saldo</th><th class="p-4">Estado</th></tr></thead><tbody><?php foreach($detalles as $d):?><tr class="border-t"><td class="p-4 font-medium"><?= htmlspecialchars($d['trabajador']) ?></td><td class="p-4">S/ <?= number_format($d['monto_pagar'],2) ?></td><td class="p-4 text-emerald-700">S/ <?= number_format($d['monto_pagado'],2) ?></td><td class="p-4 text-rose-700">S/ <?= number_format($d['saldo_pendiente'],2) ?></td><td class="p-4"><?= htmlspecialchars($d['estado']) ?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="overflow-hidden rounded-2xl border bg-white"><div class="border-b p-4"><h2 class="font-semibold">Pagos y constancias</h2><p class="text-sm text-slate-500">Cada pago genera su propio código y documento imprimible.</p></div><div class="overflow-x-auto"><table data-datatable data-page-options="5,10,25,50" class="min-w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500"><tr><th class="p-4">Código</th><th class="p-4">Trabajador</th><th class="p-4">Importe / medio</th><th class="p-4">Responsable / fecha</th><th class="p-4">Estado</th><th class="no-sort p-4">Acciones</th></tr></thead><tbody><?php foreach($pagos as $p):$codigo='PL-'.date('Y',strtotime($p['pagado_en'])).'-'.str_pad((string)$p['id_pago_planilla'],6,'0',STR_PAD_LEFT);?><tr class="border-t"><td class="p-4 font-semibold text-blue-700"><?= $codigo ?></td><td class="p-4 font-medium"><?= htmlspecialchars($p['trabajador']) ?></td><td class="p-4">S/ <?= number_format($p['importe'],2) ?><small class="block text-slate-500"><?= htmlspecialchars($p['medio_pago'].' · '.($p['referencia']?:'Sin referencia')) ?></small></td><td class="p-4 text-xs"><?= htmlspecialchars($p['responsable']) ?><br><?= htmlspecialchars($p['pagado_en']) ?></td><td class="p-4"><?= htmlspecialchars($p['estado']) ?><?php if($p['motivo_anulacion']):?><small class="block text-rose-600"><?= htmlspecialchars($p['motivo_anulacion']) ?></small><?php endif;?></td><td class="p-4"><div class="flex flex-wrap gap-2"><a target="_blank" href="index.php?url=planilla_pago_constancia&id=<?= $p['id_pago_planilla'] ?>" class="rounded-lg bg-blue-100 px-3 py-2 text-xs font-semibold text-blue-700"><i class="bi bi-printer"></i> Imprimir constancia</a><?php if($p['estado']==='REGISTRADO'):?><form method="post" action="index.php?url=planilla_pago_anular" data-confirmar-accion="planilla-pago-anular" class="flex gap-2"><?= campoCsrf() ?><input type="hidden" name="id_periodo_pago" value="<?= $periodo['id_periodo_pago'] ?>"><input type="hidden" name="id_pago_planilla" value="<?= $p['id_pago_planilla'] ?>"><input required minlength="3" name="motivo_anulacion" class="form-input mt-0 w-36" placeholder="Motivo"><button class="rounded-lg bg-rose-100 px-3 text-xs font-semibold text-rose-700">Anular</button></form><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$pagos):?><tr><td colspan="6" class="p-8 text-center text-slate-500">Todavía no hay pagos; la constancia aparecerá después de registrar el primero.</td></tr><?php endif;?></tbody></table></div></section>
